const body = $json.body || $json;
const ALLOWED_STATUSES = ['PENDING', 'IN_PROGRESS', 'COMPLETED', 'FAILED'];

if (!body.pdf_acquisition_job_id) {
  throw new Error('pdf_acquisition_job_id is required');
}

if (body.status !== undefined && !ALLOWED_STATUSES.includes(body.status)) {
  throw new Error('status must be one of: ' + ALLOWED_STATUSES.join(', '));
}

// knowledge_source_id, pdf_document_id, and started_at are fixed at
// Create time -- only a job's execution result progresses (mirrors
// acquisition_job's WP-000 design decision, 040C).
const updatable = ['status', 'finished_at', 'validation_errors'];

const fields = {};
for (const key of updatable) {
  if (body[key] !== undefined) {
    fields[key] = body[key];
  }
}

if (Object.keys(fields).length === 0) {
  throw new Error('at least one updatable field is required');
}

return [{
  json: {
    pdf_acquisition_job_id: body.pdf_acquisition_job_id,
    fields
  }
}];

const { pdf_acquisition_job_id, fields } = $json;
const keys = Object.keys(fields);

const setClauses = keys.map((key, idx) => `${key} = $${idx + 1}`);
setClauses.push('updated_at = NOW()');

const params = keys.map((key) => fields[key]);
params.push(pdf_acquisition_job_id);

const query = `UPDATE pdf_acquisition_job SET ${setClauses.join(', ')} WHERE pdf_acquisition_job_id = $${params.length} RETURNING *;`;

return [{
  json: {
    pdf_acquisition_job_id,
    query,
    params
  }
}];

const row = $input.first()?.json;

if (!row || !row.pdf_acquisition_job_id) {
  return [{
    json: {
      statusCode: 404,
      success: false,
      message: 'PDF Acquisition Job not found',
      data: null
    }
  }];
}

return [{
  json: {
    statusCode: 200,
    success: true,
    message: 'PDF Acquisition Job updated successfully',
    data: row
  }
}];
